struct Text {
    char* out;
    std::size_t capacity;
    std::size_t used = 0;
    template <class... A>
    void add(const char* format, A... args) noexcept
    {
        if (used >= capacity) return;
        const int n = std::snprintf(out + used, capacity - used, format, args...);
        if (n > 0) used += static_cast<std::size_t>(n) < capacity - used ? static_cast<std::size_t>(n) : capacity - used - 1;
    }
};

